edits.newText:
  li.classList.add("is-dragging");
  ul.classList.add("is-reordering");
  // плейсхолдер: пустое место, которое движется вместе с курсором
  const ph = document.createElement("li");
  ph.style.height = liHeight + "px";
  ph.setAttribute("aria-hidden","true");
  ph.style.pointerEvents = "none";
  ph.style.border = "0";
  ph.style.background = "transparent";
  ph.style.listStyle = "none";
  ul.insertBefore(ph, li);

  const place = clientY => {
    let idx = 0;
    const others = Array.from(ul.children).filter(c => c !== ph);
    for (const s of others) {
      const r = s.getBoundingClientRect();
      if (clientY < r.top + r.height / 2) break;
      idx++;
    }
    ph.parentNode.insertBefore(ph, others[idx] || null);
  };

  const move = ev => {
    ghost.style.top = (ev.clientY - offsetY) + "px";
    ghost.style.left = (ev.clientX - offsetX) + "px";
    place(ev.clientY);
  };
  const commit = () => {
    // li сейчас после ph — вставляем перед nim = его новое место
    ul.insertBefore(li, ph);
    ul.removeChild(ph);
  };
  const finish = () => {
    unbind();
    ul.classList.remove("is-reordering");
    li.classList.remove("is-dragging");
    commit();
    ghost.remove();
    state[si][ci] = Array.from(ul.children).map(c => c.dataset.type);
    refreshPosNumbers();
  };
  const cancel = () => {
    unbind();
    ul.classList.remove("is-reordering");
    li.classList.remove("is-dragging");
    commit(); // позиция не изменилась — восстанавливаем порядок
    ghost.remove();
    refreshPosNumbers();
  };
  const unbind = () => {
    window.removeEventListener("pointermove", move);
    document.removeEventListener("pointerup", finish);
    document.removeEventListener("pointercancel", cancel);
  };

  window.addEventListener("pointermove", move);
  document.addEventListener("pointerup", finish);
  document.addEventListener("pointercancel", cancel);
}

edits.oldText:
  li.classList.add("is-dragging");
  ul.classList.add("is-reordering");
  // плейсхолдер: пустое место
  const ph = document.createElement("li");
  ph.style.height = liHeight + "px";
  ph.setAttribute("aria-hidden","true");
  ph.style.pointerEvents = "none";
  ph.style.border = "0";
  ph.style.background = "transparent";
  ph.style.listStyle = "none";
  ul.insertBefore(ph, li);
  ul.removeChild(li);
  ul.appendChild(li); // временно — будет вставляться рядом с ph

  let moved = false;
  const computeIndex = clientY => {
    const siblings = Array.from(ul.children).filter(c => c !== ph);
    let idx = 0;
    for (const s of siblings) {
      const r = s.getBoundingClientRect();
      if (clientY < r.top + r.height / 2) break;
      idx++;
    }
    return idx;
  };
  const place = clientY => {
    let idx = 0;
    const others = Array.from(ul.children).filter(c => c !== ph && c !== li);
    for (const s of others) {
      const r = s.getBoundingClientRect();
      if (clientY < r.top + r.height / 2) break;
      idx++;
    }
    // вставляем ph по индексу; li сразу за ph
    ul.insertBefore(ph, others[idx] || null);
    ul.insertBefore(li, ph.nextSibling);
    refreshPosNumbers();
  };

  const move = ev => {
    const y = ev.clientY - startY;
    if (Math.abs(y) > 2) moved = true;
    ghost.style.top = (e.clientY + y - 0) + "px";
    ghost.style.left = Math.min(Math.max(4, e.clientX + 0), window.innerWidth - ghost.offsetWidth - 4) + "px";
    place(ev.clientY);
  };
  const finish = () => {
    document.body.removeEventListener("pointermove", move, true);
    document.body.removeEventListener("pointerup", finish, true);
    document.body.removeEventListener("pointercancel", cancel, true);
    ul.classList.remove("is-reordering");
    li.classList.remove("is-dragging");
    // зафиксировать порядок: li уже в DOM рядом с ph — убираем ph
    ul.insertBefore(li, ph);
    ul.removeChild(ph);
    ghost.remove();
    // синхронизируем state с DOM
    const order = Array.from(ul.children).map(c => c.dataset.type);
    state[si][ci] = order;
    refreshPosNumbers();
  };
  const cancel = () => {
    document.body.removeEventListener("pointermove", move, true);
    document.body.removeEventListener("pointerup", finish, true);
    document.body.removeEventListener("pointercancel", cancel, true);
    ul.classList.remove("is-reordering");
    li.classList.remove("is-dragging");
    if (moved) {
      // перестановка уже в DOM — фиксируем
      ul.insertBefore(li, ph);
      const order = Array.from(ul.children).map(c => c.dataset.type);
      state[si][ci] = order;
    } else {
      // откат: вернуть li на исходное место
      const items = Array.from(ul.children).filter(c => c !== ph && c !== li);
      ul.insertBefore(li, items[0] || items[1] || null);
      // проще: вернуть на начало (исходное местоположение неизвестно точно)
      ul.insertBefore(li, ul.children[0] === ph ? ul.children[1] : ul.children[0]);
    }
    ul.removeChild(ph);
    ghost.remove();
    refreshPosNumbers();
  };

  window.addEventListener("pointermove", move, {passive:true});
  document.addEventListener("pointerup", finish);
  document.addEventListener("pointercancel", cancel);
}

