  ]
];
const STEP_NAMES = ["Первый","Второй","Третий","Четвертый","Пятый","Шестой","Седьмой","Восьмой"];

const LETTER_INFO = {
  d:{name:"Доминирование (D)",color:"#E15252",
    desc:"Решительность, активность, целеустремлённость. Склонность брать на себя ответственность и вести за собой."},
  i:{name:"Внедрение (I)",color:"#F29B38",
    desc:"Коммуникабельность, энтузиазм, оптимизм. Ориентация на людей и создание позитивной атмосферы."},
  s:{name:"Стабильность (S)",color:"#3A944A",
    desc:"Строгость, ответственность, системность. Осторожный, взвешенный подход к решениям."},
  c:{name:"Соблюдение правил (C)",color:"#1F5BD6",
    desc:"Сосредоточенность, тщательность, внимание к деталям. Точность и выверенность в действиях."}
};

/* ================= состояние ================= */
// state[step][card] = массив типов в текущем порядке (индекс = позиция)
let state = [];
function freshState(){
  return STEPS.map(step => step.map(card => card.map(t => t[0])));
}
state = freshState();

let step = 0;
const TOTAL = STEPS.length;

/* ================= DOM ================= */
const $ = s => document.querySelector(s);
const tabsEl = $("#tabs"), bodyEl = $("#body");
const btnPrev = $("#btnPrev"), btnNext = $("#btnNext"), btnFinish = $("#btnFinish");
const progress = $("#discProgress"), actions = $("#actions"), resultsEl = $("#results");
const resultsGrid = $("#resultsGrid");

const HANDLE_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="none" aria-hidden="true">' +
  '<circle cx="5" cy="4" r="1.6" fill="#B3B3B3"/><circle cx="9" cy="4" r="1.6" fill="#B3B3B3"/>' +
  '<circle cx="5" cy="8" r="1.6" fill="#B3B3B3"/><circle cx="9" cy="8" r="1.6" fill="#B3B3B3"/>' +
  '<circle cx="5" cy="12" r="1.6" fill="#B3B3B3"/><circle cx="9" cy="12" r="1.6" fill="#B3B3B3"/></svg>';

function esc(s){return String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}

/* ================= рендер ================= */
function buildTabs(){
  tabsEl.innerHTML = STEP_NAMES.map((n,i) =>
    `<button class="disc-tab" type="button" role="tab" data-step-btn="${i}">${esc(n)}</button>`
  ).join("");
  tabsEl.querySelectorAll(".disc-tab").forEach(t =>
    t.addEventListener("click", () => setStep(Number(t.dataset.stepBtn))));
}

function buildPanes(){
  bodyEl.innerHTML = "";
  STEPS.forEach((cards, si) => {
    const pane = document.createElement("div");
    pane.className = "disc-pane";
    pane.setAttribute("data-step-pane", si);
    pane.setAttribute("role","tabpanel");
    pane.innerHTML = '<div class="disc-grid3"></div>';
    const grid = pane.querySelector(".disc-grid3");
    cards.forEach((card, ci) => {
      const cardEl = document.createElement("div");
      cardEl.className = "disc-card";
      const ul = document.createElement("ul");
      ul.className = "disc-list";
      ul.dataset.step = si; ul.dataset.card = ci;
      card.forEach(([type,label]) => {
        const li = document.createElement("li");
        li.className = "disc-item";
        li.dataset.type = type;
        li.innerHTML = `<span class="pos" aria-hidden="true"></span><span class="disc-item__label">${esc(label)}</span><span class="disc-handle" aria-hidden="true">${HANDLE_SVG}</span>`;
        ul.appendChild(li);
        attachSortable(ul, li);
      });
      cardEl.innerHTML = "";
      cardEl.appendChild(Object.assign(document.createElement("div"),{className:"disc-card__title",textContent:"Я наиболее"}));
      cardEl.appendChild(ul);
      cardEl.appendChild(Object.assign(document.createElement("div"),{className:"disc-card__foot",textContent:"Я наименее"}));
      grid.appendChild(cardEl);
    });
    bodyEl.appendChild(pane);
  });
  // после создания панелей заполняем номера позиций заново
  refreshPosNumbers();
}

function refreshPosNumbers(){
  document.querySelectorAll(".disc-pane .disc-item .pos").forEach(() => {});
  for (const ul of document.querySelectorAll(".disc-list")) {
    const si = Number(ul.dataset.step), ci = Number(ul.dataset.card);
    const order = state[si][ci];
    Array.from(ul.children).forEach((li, idx) => {
      li.querySelector(".pos").textContent = idx + 1;
      li.dataset.type = order[idx];
    });
  }
}

function render(){
  // вкладки
  tabsEl.querySelectorAll(".disc-tab").forEach(t => {
    const is = Number(t.dataset.stepBtn) === step;
    t.classList.toggle("is-active", is);
    t.setAttribute("aria-selected", is ? "true" : "false");
  });
  bodyEl.querySelectorAll(".disc-pane").forEach(p =>
    p.classList.toggle("is-active", Number(p.dataset.stepPane) === step));

  btnPrev.disabled = step === 0;
  btnNext.hidden = step === TOTAL - 1;
  btnFinish.hidden = step !== TOTAL - 1;
  progress.style.width = (((step + 1) / TOTAL) * 100) + "%";

  bodyEl.scrollTop = 0;
  // центрируем активную вкладку на мобильном
  const active = tabsEl.querySelector(".disc-tab.is-active");
  if (active && tabsEl.scrollWidth > tabsEl.clientWidth) {
    tabsEl.scrollTo({left: active.offsetLeft - (tabsEl.clientWidth - active.offsetWidth)/2, behavior:"smooth"});
  }
}

function setStep(n){
  step = Math.max(0, Math.min(TOTAL - 1, n));
  render();
}

btnPrev.addEventListener("click", () => setStep(step - 1));
btnNext.addEventListener("click", () => setStep(step + 1));
btnFinish.addEventListener("click", showResults);
$("#btnRestart").addEventListener("click", () => {
  state = freshState();
  buildPanes();
  step = 0;
  resultsEl.classList.remove("is-active");
  actions.style.display = "";
  tabsEl.style.display = "";
  progress.parentElement.style.display = "";
  document.querySelector(".disc-modal__head .disc-modal__sub").textContent = "Помните — чем честнее вы с тестом, тем точнее результаты!";
  document.querySelector(".disc-modal__head .disc-modal__lead").textContent = "Разместите блоки в порядке от наиболее похожего на вас до наименее похожего";
  render();
});

/* ================= drag & drop (pointer events: мышь + тач) =================
   Тащим за весь элемент; порядок обновляем на лету, state — при завершении. */
let dragState = null;

function attachSortable(ul, li){
  li.addEventListener("pointerdown", e => {
    if (e.button !== 0 && e.pointerType === "mouse") return;
    if (document.querySelector(".disc-pane.is-active") !== ul.closest(".disc-pane")) return;
    if (resultsEl.classList.contains("is-active")) return;
    e.preventDefault();
    startDrag(ul, li, e);
  });
}

function startDrag(ul, li, e){
  const items = Array.from(ul.querySelectorAll("li"));
  const si = Number(ul.dataset.step), ci = Number(ul.dataset.card);
  const offsetY = e.clientY - li.getBoundingClientRect().top;
  const offsetX = e.clientX - li.getBoundingClientRect().left;
  const liHeight = li.offsetHeight + 1; // +бorders
  const rect = ul.getBoundingClientRect();

  const ghost = li.cloneNode(true);
  ghost.style.width = li.offsetWidth + "px";
  ghost.style.position = "fixed";
  ghost.style.left = li.getBoundingClientRect().left + "px";
  ghost.style.top = li.getBoundingClientRect().top + "px";
  ghost.style.zIndex = 50;
  ghost.style.pointerEvents = "none";
  ghost.style.opacity = ".95";
  ghost.style.boxShadow = "0 10px 26px rgba(31,91,214,.28)";
  document.body.appendChild(ghost);

  li.style.display = "none"; // оригинал скрыт, виден только ghost
  ul.classList.add("is-reordering");
  // плейсхолдер: пустое место, которое движется вместе с курсором
  const ph = document.createElement("li");
  ph.style.height = liHeight + "px";
  ph.setAttribute("aria-hidden","true");
  ph.style.pointerEvents = "none";
  ph.style.border = "0";
  ph.style.background = "transparent";
  ph.style.listStyle = "none";
  ul.insertBefore(ph, li);

  const place = clientY => {
    let idx = 0;
    const others = Array.from(ul.children).filter(c => c !== ph);
    for (const s of others) {
      const r = s.getBoundingClientRect();
      if (clientY < r.top + r.height / 2) break;
      idx++;
    }
    ph.parentNode.insertBefore(ph, others[idx] || null);
  };

  const move = ev => {
    ghost.style.top = (ev.clientY - offsetY) + "px";
    ghost.style.left = (ev.clientX - offsetX) + "px";
    place(ev.clientY);
  };
  const commit = () => {
    // li сейчас рядом с ph (прямо после него) — вставляем перед ph = его новое место
    ul.insertBefore(li, ph);
    ul.removeChild(ph);
    li.style.display = ""; // возвращаем отображение
  };
  const finish = () => {
    unbind();
    ul.classList.remove("is-reordering");
    commit();
    ghost.remove();
    state[si][ci] = Array.from(ul.children).map(c => c.dataset.type);
    refreshPosNumbers();
  };
  const cancel = () => {
    unbind();
    ul.classList.remove("is-reordering");
    commit(); // ph возвращает li на исходную позицию (если не двигали)
    ghost.remove();
    refreshPosNumbers();
  };
  const unbind = () => {
    window.removeEventListener("pointermove", move);
    document.removeEventListener("pointerup", finish);
    document.removeEventListener("pointercancel", cancel);
  };

  window.addEventListener("pointermove", move);
  document.addEventListener("pointerup", finish);
  document.addEventListener("pointercancel", cancel);
}

/* ================= подсчёт ================= */
function computeScore(){
  const maj = [], min = [];
  for (const card of state) {
    card.forEach(order => {
      if (order[0]) maj.push(order[0]);
      if (order[3]) min.push(order[3]);
    });
  }
  const count = (a, ch) => a.reduce((n,v) => n + (v===ch?1:0), 0);
  return {
    d: count(maj,"d") - count(min,"d"),
    i: count(maj,"i") - count(min,"i"),
    s: count(maj,"s") - count(min,"s"),
    c: count(maj,"c") - count(min,"c")
  };
}

function showResults(){
  const sc = computeScore();
  resultsEl.classList.add("is-active");
  tabsEl.style.display = "none";
  actions.style.display = "none";
  progress.parentElement.style.display = "none";
  document.querySelector(".disc-modal__head .disc-modal__sub").textContent = "Готово! Вот ваши результаты.";
  document.querySelector(".disc-modal__head .disc-modal__lead").textContent = "Расставьте блоки заново, чтобы пройти тест ещё раз.";

  const maxAbs = Math.max(1, sc.d, sc.i, sc.s, sc.c);
  resultsGrid.innerHTML = ["d","i","s","c"].map(k => {
    const info = LETTER_INFO[k];
    const v = sc[k];
    const pct = Math.round(Math.abs(v)/maxAbs*100);
    return `<div class="score-card" data-letter="${k.toUpperCase()}">
      <div class="score-card__badge">${k.toUpperCase()}</div>
      <div>
        <p class="score-card__name">${esc(info.name)}</p>
        <p class="score-card__desc">${esc(info.desc)}</p>
        <div class="score-card__meter"><i style="width:${pct}%;background:${info.color}"></i></div>
        <div class="score-card__val">Балл: ${v > 0 ? "+" + v : v}</div>
      </div>
    </div>`;
  }).join("");
  bodyEl.scrollTo({top:0,behavior:"smooth"});
  window.scrollTo({top:0,behavior:"smooth"});
}

/* ================= init ================= */
buildTabs();
buildPanes();
render();
</script>
</body>
</html>

